  FT["PH-H5277"] = {"id":"PH-H5277","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6781_1989.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Loon District Hospital in the Municipality of Loon, Province of Bohol, to Congressman Natalio P. Castillo, Sr. Memorial Hospital","orig":"An Act Changing the Name of the Loon District Hospital in the Municipality of Loon, Province of Bohol, to Congressman Natalio P. Castillo, Sr. Memorial Hospital"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6781","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-11-29","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6781_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5277-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Loon District Hospital in the Municipality of Loon, Province of Bohol, is hereby changed to Congressman Natalio P. Castillo, Sr. Memorial Hospital."}},{"id":"PH-H5277-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"If, for any reason, any section or provision of this Act is declared unconstitutional, the other provisions hereof shall not be affected and shall remain in full force and effect."}},{"id":"PH-H5277-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All laws, executive orders, decrees and proclamations or any part or parts thereof inconsistent with the provisions of this Act are deemed repealed or amended accordingly."}},{"id":"PH-H5277-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p75"};
