  FT["PH-H5301"] = {"id":"PH-H5301","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6805_1989.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Pastrana Municipal High School in the Municipality of Pastrana, Province of Leyte, to Juan Villablanca Memorial High School","orig":"An Act Changing the Name of the Pastrana Municipal High School in the Municipality of Pastrana, Province of Leyte, to Juan Villablanca Memorial High School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 6805","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-12-12","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6805_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5301-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Pastrana Municipal High School in the Municipality of Pastrana, Province of Leyte, is hereby changed to Juan Villablanca Memorial High School."}},{"id":"PH-H5301-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p75"};
  FT["PH-H5302"] = {"id":"PH-H5302","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6806_1989.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Gatbuca Elementary School in the Municipality of Calumpit, Province of Bulacan, to Arsenio Santos Memorial Elementary School","orig":"An Act Changing the Name of the Gatbuca Elementary School in the Municipality of Calumpit, Province of Bulacan, to Arsenio Santos Memorial Elementary School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 6806","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-12-12","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6806_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5302-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Gatbuca Elementary School in the Municipality of Calumpit, Province of Bulacan, is hereby changed to Arsenio Santos Memorial Elementary School."}},{"id":"PH-H5302-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p75"};
  FT["PH-H5303"] = {"id":"PH-H5303","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6807_1989.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Converting the Mati Community College into a State College to be known as the Davao Oriental, State College of Science and Technology, Providing for a Charter for This Purpose, Expanding Its Curricular Offerings, Redirecting Its Objectives, and Appropriating Funds Therefor","orig":"An Act Converting the Mati Community College into a State College to be known as the Davao Oriental, State College of Science and Technology, Providing for a Charter for This Purpose, Expanding Its Curricular Offerings, Redirecting Its Objectives, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 6807","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-12-13","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6807_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5303-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The present Mati Community College located in the Municipality of Mati, Province of Davao Oriental, is hereby converted into a state college to be known as the Davao Oriental State College of Science and Technology, hereinafter referred to as the State College."}},{"id":"PH-H5303-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The State College shall primarily provide higher technological, professional, and vocational instruction and training in science, agriculture, fishery, forestry, engineering and industrial fields, as well as short-term technical or vocational courses. It shall also promote research, advanced studies and progressive leadership in its areas of specialization."}},{"id":"PH-H5303-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"In addition to its present curricular offerings, the State College shall offer undergraduate and graduate courses in the fields of science, agriculture, fishery, forestry and engineering as the Board of Trustees may deem necessary. It shall also offer short-term technical or vocational courses, provide non-formal education and undertake vigorous extension and research programs in food production, nutrition, health and sports development."}},{"id":"PH-H5303-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"No student shall be denied admission to the State College by reason of sex, ethnic considerations, or religious belief or affiliation."}},{"id":"PH-H5303-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The head of the State College shall be known as the President of the Davao Oriental State College of Science and Technology who shall be appointed by the Board of Trustees. He shall hold office for a term of six (6) years without reappointment, unless he reaches the age of retirement or earlier removed for cause or incapacitated to discharge the duties of the office. In case of vacancy by reason of death, resignation, removal for cause or incapacity of the President to perform the functions of his office, the Board shall have the authority to designate an officer-in-charge of the State College pending the appointment of a new President.\nIn case of vacancy in the Office of the President as mentioned in the immediately preceding paragraph, his successor shall hold office for the unexpired term but in no case shall his term be more than six (6) years.\nHis salary shall be fixed by the Board of Trustees comparable to that being received by the President of similar educational institutions of like enrollment and standing.\nThe powers and duties of the President of the State College, in addition to those specifically provided for in this Act, shall be those usually pertaining to the office of the president of a state college or university."}},{"id":"PH-H5303-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The governing board of the State College shall be the Board of Trustees of the Davao Oriental State College of Science and Technology. It shall be composed of the following:\nSecretary of Education, Culture and Sports, chairman"}}],"pack":"ph-p75"};
  FT["PH-H5304"] = {"id":"PH-H5304","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6808_1989.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Naming the Plaridel-Bustos-Angat-Norzagaray-Santa Maria Highway in the Province of Bulacan as the General Alejo G. Santos Highway","orig":"An Act Naming the Plaridel-Bustos-Angat-Norzagaray-Santa Maria Highway in the Province of Bulacan as the General Alejo G. Santos Highway"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6808","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-12-13","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6808_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5304-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Plaridel-Bustos-Angat-Norzagaray-Santa Maria Highway in the Province of Bulacan is hereby named as the General Alejo G. Santos Highway."}},{"id":"PH-H5304-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p75"};
  FT["PH-H5305"] = {"id":"PH-H5305","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6809_1989.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Lowering the Age of Majority from Twenty-One to Eighteen Years, amending for the Purpose Executive Order Numbered Two Hundred Nine, and for other purposes","orig":"An Act Lowering the Age of Majority from Twenty-One to Eighteen Years, amending for the Purpose Executive Order Numbered Two Hundred Nine, and for other purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6809","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-12-13","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6809_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5305-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Article 234 of Executive Order No. 209, the Family Code of the Philippines, is hereby amended to read as follows:\n\"Art. 234. Emancipation takes place by the attainment of majority. Unless otherwise provided, majority commences at the age of eighteen years.\""}},{"id":"PH-H5305-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Articles 235 and 237 of the same Code are hereby repealed."}},{"id":"PH-H5305-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Article 236 of the same Code is also hereby amended to read as follows:\n\"Art. 236. Emancipation shall terminate parental authority over the person and property of the child who shall then be qualified and responsible for all acts of civil life, save the exceptions established by existing laws in special cases.\n\"Contracting marriage shall require parental consent until the age of twenty-one.\n\"Nothing in this Code shall be construed to derogate from the duty or responsibility of parents and guardians for children and wards below twenty-one years of age mentioned in the second and third paragraphs of Article 2180 of the Civil Code.\""}},{"id":"PH-H5305-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Upon the effectivity of this Act, existing wills, bequests, donations, grants, insurance policies and similar instruments containing references and provisions favorable to minors will not retroact to their prejudice."}},{"id":"PH-H5305-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon completion of its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p75"};
  FT["PH-H5306"] = {"id":"PH-H5306","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6810_1989.html","fetchedAt":"2026-10-06","articleCount":14,"structureMode":"ARTICLE","title":{"zh":null,"en":"Magna Carta for Countryside and Barangay Business Enterprises","orig":"Magna Carta for Countryside and Barangay Business Enterprises An Act Establishing the Magna Carta for Countryside and Barangay Business Enterprises, Granting Exemptions from any and all Government Rules and Regulations and other Incentives and Benefits Therefor, and for other purposes"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 6810","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-12-14","completenessNote":"全文，共 14 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6810_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5306-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"It is hereby declared to be the policy of the State that growth of countryside business enterprises shall be achieved through absence of bureaucratic restrictions and granting of incentives and other benefits."}},{"id":"PH-H5306-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall be known and cited as the \" Magna Carta for Countryside and Barangay Business Enterprises ( Kalakalan 20 ).\"\nAs used in this Act, the term \"countryside and barangay business enterprises,\" hereinafter referred to as the CBBE ( Kalakalan 20 ), shall mean any business entity, association or cooperative registered under the provisions of this Act whose:\n(a) Number of employees does not exceed twenty (20) at any time for the purpose of undertaking a productive business enterprise recommended by the Department of Trade and Industry (DTI) provincial office that will help develop the economy in its area.\nFor this purpose, the term \"productive business enterprise\" shall not apply to business enterprises engaged principally in any of the following activities, namely: professional services, retailing, wholesaling or trading of commodities, products or merchandise;\n(b) Assets, at the time of registration as CBBE, do not exceed Five hundred thousand pesos (P500,000.00) before financing; and\n(c) Principal office and location of business operations are located in the countryside as defined in the implementing rules and regulations issued by the Secretary of Trade and Industry."}},{"id":"PH-H5306-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Countryside business entities shall, upon registration, pay Two hundred and fifty pesos (P250.00) to the municipality or city where its principal place of office and business operations are located to cover the cost of the issuance of the license to operate, known as the CBBE authority.\nAll CBBEs shall be exempted from all taxes, national or local, license and building permit fees and other business taxes, except real property and capital gains taxes, import duties and other taxes on imported articles. In addition, any and all income, receipts and proceeds derived from the business operations of the CBBE shall be excluded from the computation of gross income for purposes of computing the individual income tax of the owners/members thereof.\nIt shall be exempted from any and all government rules and regulations in respect of assets, income, and other activities indispensably and directly utilized in, proceeding from or connected with the business of the enterprise.\nCBBEs, however, shall pay the CBBE fee to the municipal or city treasurer where they are registered, starting on their second year of operations, based on the following schedule:\n(a) Those with net assets before financing amounting to not more than P100,000.00 P1,000.00 per annum;\n(b) Those with net assets before financing of more than P100,000.00 to P250,000.00 P2,500.00 per annum;\n(c) Those with net assets before financing of more than P250,000.00 to P400,000.00 P4,000.00 per annum; and\n(d) Those with net assets before financing of more than P400,000.00 to P500,000.00 P5,000.00 per annum.\nIn the event the CBBE uses a brand name on its products, such brand name shall first be registered with the Bureau of Domestic Trade, through the Department of Trade and Industry (DTI) provincial office."}},{"id":"PH-H5306-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The collected CBBE fee shall accrue exclusively to the municipality or city and shall be used for developmental projects approved by the municipal or city council."}},{"id":"PH-H5306-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"CBBEs registered under the provisions of this Act shall acquire a separate and distinct juridical personality from the owners/members thereof and as such can own, dispose and encumber its properties and enter into contracts on its own account, with the capacity to sue and be sued, and transact business anywhere in the country."}},{"id":"PH-H5306-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The CBBE shall, as far as practicable, recruit its employees and utilize the indigenous and other existing resources within the areas of its operations."}},{"id":"PH-H5306-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"All the exemptions and other benefits herein provided shall, after due notice and hearing, be forfeited in case of any violation of the provisions of this Act by the CBBE or by any of its officers and authorized representatives."}},{"id":"PH-H5306-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The CBBE authority shall, after due notice and hearing, be revoked and cancelled upon the failure of the CBBE, without valid reasons, to commence its operations within forty-five (45) days from receipt of the authority to operate."}},{"id":"PH-H5306-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The exemptions and other benefits provided in this Act shall apply for a period not exceeding five (5) years from the date of the registration of the CBBE, provided such CBBE is registered within five (5) years from the effectivity of this Act."}},{"id":"PH-H5306-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The Secretary of Trade and Industry in consultation with the Secretaries of Finance, Labor, and Health, and the local government units shall formulate and prepare the necessary rules and regulations to implement the provisions of this Act within one hundred twenty (120) days. The rules and regulations issued pursuant to this section shall take effect fifteen (15) days after publication in a newspaper of general circulation and by such other means as the Secretary of Trade and Industry may deem reasonably sufficient to give interested parties general notice of such issuance."}},{"id":"PH-H5306-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Any person who shall willfully violate any provisions of this Act or who shall in any other manner commit any act to defeat any provisions of this Act shall, upon conviction, be punished by a fine of not less than One thousand pesos (P1,000.00) nor more than Ten thousand pesos (P10,000.00): Provided, however, That should the same act or omission committed under this section be likewise covered by another law, decree or order which provides for heavier penalty, the latter shall be made applicable: Provided, further, That should the act or omission punishable under this section be committed by a public official, the latter shall be prosecuted under the provisions of existing applicable laws."}},{"id":"PH-H5306-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"All laws or parts thereof, decrees, orders, rules and regulations inconsistent with the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H5306-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"If any of the provisions of this Act is declared invalid, the remainder of this Act or any provision not affected thereby shall remain in force and effect."}},{"id":"PH-H5306-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p75"};
