  FT["PH-H5320"] = {"id":"PH-H5320","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6824_1989.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Buayan Elementary School to Datu Acad Dalid Central Elementary School","orig":"An Act Changing the Name of the Buayan Elementary School to Datu Acad Dalid Central Elementary School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 6824","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-12-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6824_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5320-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Buayan Elementary School in General Santos City, Province of South Cotabato, shall hereafter be known and referred to as the Datu Acad Dalid Central Elementary School."}},{"id":"PH-H5320-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p75"};
  FT["PH-H5321"] = {"id":"PH-H5321","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6825_1989.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Sta. Lucia Elementary School in the Municipality of Calumpit, Province of Bulacan, to Pascual O. Cruz Elementary School","orig":"An Act Changing the Name of the Sta. Lucia Elementary School in the Municipality of Calumpit, Province of Bulacan, to Pascual O. Cruz Elementary School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 6825","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-12-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6825_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5321-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Sta. Lucia Elementary School in the Municipality of Calumpit, Province of Bulacan, is hereby changed to Pascual O. Cruz Elementary School."}},{"id":"PH-H5321-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p75"};
  FT["PH-H5322"] = {"id":"PH-H5322","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6826_1989.html","fetchedAt":"2026-10-06","articleCount":9,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Declare, in View of the Existence of a National Emergency, a National Policy in Connection Therewith and to Authorize the President of the Republic of the Philippines for a limited Period and Subject to Restrictions, to Exercise Powers Necessary and Proper to Carry Out the Declared National Policy and for other purposes","orig":"An Act to Declare, in View of the Existence of a National Emergency, a National Policy in Connection Therewith and to Authorize the President of the Republic of the Philippines for a limited Period and Subject to Restrictions, to Exercise Powers Necessary and Proper to Carry Out the Declared National Policy and for other purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6826","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-12-20","completenessNote":"全文，共 9 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6826_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5322-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"State of National Emergency. - On December 1, 1989, a rebellion committed by certain elements of the Armed Forces of the Philippines aided and abetted by civilians gave rise to an emergency of national proportions.\nThe emergency continues even with the cessation of military hostilities. More than 2,000 persons who participated in the failed coup, including the masterminds and plotters, are said to be still at large. There is a clear threat to national security posed by the rebels who have just \"returned to their barracks,\" and the fence-sitters among the military. Bombings in Metropolitan Manila continue causing loss of lives, maiming of limbs and destruction of property.\nOn December 6, 1989, Proclamation No. 503 was issued by the President declaring a state of national emergency.\nMeanwhile, secessionist elements in Mindanao, seeking to establish a common cause with rebels and their sympathizers, or taking advantage of the instability occasioned by the coup, are reported to have taken overt acts to dismember the country.\nCommunist rebels have taken advantage of the situation by attacking Government personnel and installations.\nThe economy has suffered and continues to suffer a serious setback, severely disrupting the momentum of our economic recovery.\nA state of national emergency is hereby declared."}},{"id":"PH-H5322-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy. - The mutiny and rebellion by certain elements of the Armed Forces of the Philippines launched to seize state power, destabilize the duly constituted Government and supplant it with a military government by means of force and violence and other illegal means, has caused loss of lives and destruction of property and has set back the economic program of the Government. Due to and by reason thereof, and in order to optimize the efforts of the President to carry out the difficult task of economic reconstruction, it is imperative to grant her emergency powers subject to such limitations as hereinafter provided."}},{"id":"PH-H5322-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Authorized Powers. - Pursuant to Article VI, Section 23 (2) of the Constitution, and to implement the declared national policy, the President is hereby authorized to issue such rules and regulations as may be necessary to carry out any or all of the following powers:\n(1) To protect the people from hoarding, profiteering, injurious speculations, manipulation of prices, product deceptions, and cartels, monopolies or other combinations in restraint of trade, or other pernicious practices affecting the supply, distribution and movement of food, clothing, medicine and medical supplies, office and school supplies, fuel, fertilizers, chemicals, building materials, implements, machinery equipment and spare parts required in agriculture, industry and other essential services, and other articles of prime necessity, whether imported or locally produced or manufactured;\n(2) Towards the above ends, (a) to purchase any of the articles or commodities hereinabove mentioned, for storage, sale, or distribution for the relief of hunger and want of the population, and/or to stabilize the prices of such foodstuffs, articles and other commodities; (b) to fix the maximum selling prices thereof; (c) to regulate the fees charged by establishments in connection with the production, processing, milling, storage and distribution of such articles or commodities; (d) to seize and confiscate hoarded foodstuffs and commodities: Provided, That goods which are determined to have been seized wrongfully shall be subject to the subsequent determination and payment of just compensation; and (e) to call upon and deputize recognized nongovernment and people's organizations and volunteers as well as local government units to assist the Government to carry out these powers through the monitoring or implementation of orders, rules and regulations, as the case may be;\n(3) To temporarily take over or direct the operation of any privately-owned public utility or business affected with public interest that violates the herein declared national policy: Provided, however, That to the extent feasible, management shall be retained, under the direction and supervision of the President or her duly designated representative who shall render a full accounting to the President of the operations of the utility or business taken over: Provided, further, That whenever the President shall determine that the further use or operation by the Government of any such public service or enterprise is no longer necessary under existing conditions, the same shall be restored to the person entitled to the possession thereof;\n(4) To liberalize the importation and/or grant incentives for the manufacture, assembly, reconditioning, or importation of needed vehicles or vessels, including the necessary parts thereof, for public transportation to relieve the transportation crises;\n(5) To ensure the availability of credit to the productive sectors of the economy especially in the countryside through measures such as, but not limited to, lowering the effective lending rates of interest and reserve requirements of lending institutions;\n(6) To stagger the working hours of, and adopt a flexible working schedule for, employees and workers in government, and whenever it becomes necessary, in the private sector;\n(7) To conserve and regulate the distribution and use of power, fuels and energy and ensure adequate supply of the same;\n(8) Subject to the provisions of paragraph 5, Section 25, Article VI of the Constitution, to decrease expenditures of the Executive Department of the National Government and government-owned or controlled corporations and their subsidiaries through the suspension of services, activities or operations which are of no immediate necessity, and for this purpose the President shall order that all departments, agencies and instrumentalities of the government create a reserve fund equivalent to ten percent (10%) of their respective appropriations, except those pertaining to personnel services, construction and repair of school buildings and hospitals: Provided, however, That in all cases, the security of tenure of civil service employees shall be respected;\n(9) To issue lawful orders for the recovery and accounting of all firearms, explosives and military equipage, including, but not limited to, those belonging to the Armed Forces of the Philippines and the Philippine Constabulary-Integrated National Police and licensed firearms which have fallen into the possession of unauthorized persons or entities, or are being used by their holders for unlawful purposes, and pursuant thereto, adopt such measures as are reasonably necessary to take custody of such firearms, explosives and equipage and/or otherwise accomplish the purposes herein stated: Provided, That this authority can be exercised only upon specific orders of the President or her duly authorized representative;\n(10) To ensure that military uniforms, equipment and supplies of the Armed Forces of the Philippines and the Philippine Constabulary-Integrated National Police are possessed and used only by authorized officers and members thereof pursuant to law; and\n(11) To undertake such other measures as may be reasonable and necessary to enable the President to carry out the declared national policy subject to the Bill of Rights and other constitutional guarantees."}},{"id":"PH-H5322-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Reports to Congress. - The President, within ten (10) days from the issuance of any of the executive acts, orders, rules and regulations promulgated and issued by her under the powers herein granted shall report to Congress the issuance thereof and the justification therefor: Provided, That within the first ten (10) days of every month, the President shall likewise submit a monthly report to Congress of all acts performed pursuant to this Act during the preceding month."}},{"id":"PH-H5322-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Penalties. - Any violation of the rules or regulations issued pursuant hereto, shall be punishable with imprisonment of not less than five (5) years but not more than ten (10) years or a fine of not less than Fifty thousand pesos (P50,000) but not more than Five hundred thousand pesos (P500,000) or both such imprisonment and fine at the discretion of the court: Provided, however, That if the offender is a corporation, association, partnership or any other juridical person, the penalty shall be imposed upon the president, directors, managers, managing partners, as the case may be, who participated in the commission of the offense or who shall have knowingly permitted or failed to prevent the commission of the same. If the offender is an alien, he shall, in addition to the penalties herein prescribed, be deported without further proceedings; Provided, further, That if the offender is a public official or employee, he shall, in addition to the penalties prescribed herein, suffer perpetual or temporary absolute disqualification from office, as the case may be."}},{"id":"PH-H5322-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Construction or Interpretation. - Nothing in this Act shall be construed or interpreted as a restriction of the Bill of Rights or of the Constitution."}},{"id":"PH-H5322-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Separability Clause. - If any provision of this Act or the application of such provision to any person or circumstance is declared invalid, the remainder of this Act or the application of such provision to any other person or circumstances shall not be affected by such declaration."}},{"id":"PH-H5322-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Promulgation, Effect and Enforcement of Rules and Regulations. - The rules and regulations promulgated by the President pursuant to this Act, which shall have the force and effect of law, shall be numbered consecutively and shall take effect two (2) days after their publication in case of rules and regulations that are denominated \"urgent,\" and five (5) days in case of those without such denomination. The publication shall be effected in at least two (2) newspapers of national circulation.\nRules and regulations with a penal clause shall be duly published in Filipino and English in at least two (2) national newspapers of general circulation.\nSaid rules and regulations shall cease to be in force and effect upon the expiry date provided in Section 9 hereof without prejudice to benefits and rights that may have vested, and culpabilities and liabilities that may have been incurred and established after due notice and hearing."}},{"id":"PH-H5322-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Effectivity. - This Act shall take effect upon its publication in two (2) national newspapers of general circulation and shall be in full force and effect until the next sine die adjournment in June 1990 of the regular session of Congress: Provided, however, That adjournment for a recess shall not affect the duration of this Act: and Provided, further, That the powers granted under this Act may be withdrawn sooner by means of a concurrent resolution of Congress or ended by Presidential Proclamation."}}],"pack":"ph-p75"};
  FT["PH-H5323"] = {"id":"PH-H5323","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6827_1989.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Postponing the Holding of the First Regular Election for the Governor, Deputy Governor, and Members of the Regional Assembly of the Autonomous Region of the Cordilleras by amending Section One of the Transitory Provisions of Republic Act Numbered Six Thousand Seven Hundred Sixty-Six, and for other purposes","orig":"An Act Postponing the Holding of the First Regular Election for the Governor, Deputy Governor, and Members of the Regional Assembly of the Autonomous Region of the Cordilleras by amending Section One of the Transitory Provisions of Republic Act Numbered Six Thousand Seven Hundred Sixty-Six, and for other purposes"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 6827","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-12-26","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6827_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5323-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section One, Article XXI of Republic Act Numbered Six thousand seven hundred sixty-six is hereby amended to read as follows:\n\"Sec. 1. The first regular election for the Cordillera Governor, the Cordillera Deputy Governor and the Members of the Cordillera Assembly shall be held on the second Monday of March 1990. Their terms of office shall begin at noon of the last day of the month next following their election and shall end at noon of the thirty-first day of March 1993. The expenses for the conduct of the election shall be charged against the Contingent Fund; any deficiency shall be taken from the savings of the National Government. The Commission on Elections shall promulgate such rules and regulations as may be necessary for the conduct of said election.\""}},{"id":"PH-H5323-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its complete publication in at least two (2) national newspapers and at least one (1) local newspaper of general circulation in the Autonomous Region."}}],"pack":"ph-p75"};
  FT["PH-H5324"] = {"id":"PH-H5324","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6828_1989.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Extending the Effectivity of Batas Pambansa Blg. 877 Entitled \"An Act Providing for the Stabilization and Regulation of Rentals of Certain Residential Units and for Other Purposes\" for Another Three Years, Amending Thereby Section One of Republic Act Numbered Sixty-Six Hundred and Forty-Three","orig":"An Act Extending the Effectivity of Batas Pambansa Blg. 877 Entitled \"An Act Providing for the Stabilization and Regulation of Rentals of Certain Residential Units and for Other Purposes\" for Another Three Years, Amending Thereby Section One of Republic Act Numbered Sixty-Six Hundred and Forty-Three"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6828","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-12-30","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6828_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5324-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The effectivity of Batas Pambansa Blg. 877, entitled \" An Act Providing for the Stabilization and Regulation of Rentals of Certain Residential Units and For Other Purposes ,\" is hereby extended for three (3) years for the period January 1, 1990 to December 31, 1992: Provided, That the allowable maximum increase for the three-year period shall not be more than the rates herein provided:\nPeriod\nMaximum Increase\nJanuary 1, 1990 - December 31, 1990 Twenty percent (20%) January 1, 1991 - December 31, 1991 Twenty percent (20%) January 1, 1992 - December 31, 1992 Twenty percent (20%) Provided , further , That the basis for the maximum increase herein authorized for the three-year period shall be the actual monthly rental as of December 31, 1989: Provided, finally, That the increases authorized herein shall be cumulative and compounded."}},{"id":"PH-H5324-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect on January 1, 1990 following its publication in at least two (2) national newspapers of general circulation."}}],"pack":"ph-p75"};
  FT["PH-H5325"] = {"id":"PH-H5325","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6829_1989.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Renaming Barangay Pacalcal in the Municipality of Bamban, Province of Tarlac, to be known as Barangay De Los Remedios, and for other purposes","orig":"An Act Renaming Barangay Pacalcal in the Municipality of Bamban, Province of Tarlac, to be known as Barangay De Los Remedios, and for other purposes"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 6829","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-12-30","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6829_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5325-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Barangay Pacalcal in the Municipality of Bamban, Province of Tarlac, is hereby renamed as Barangay de los Remedios."}},{"id":"PH-H5325-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Local Government, through the Sangguniang Panlalawigan of Tarlac and the Sangguniang Bayan of Bamban, is hereby directed to carry out the purpose of this Act."}},{"id":"PH-H5325-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p75"};
  FT["PH-H5326"] = {"id":"PH-H5326","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6830_1989.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Municipality of Bacungan, Province of Zamboanga Del Norte, to Municipality of Leon T. Postigo","orig":"An Act Changing the Name of the Municipality of Bacungan, Province of Zamboanga Del Norte, to Municipality of Leon T. Postigo"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6830","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-12-30","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6830_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5326-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Municipality of Bacungan, Province of Zamboanga del Norte, created under Batas Pambansa Blg. 204, is hereby changed to Municipality of Leon T. Postigo."}},{"id":"PH-H5326-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p75"};
  FT["PH-H5327"] = {"id":"PH-H5327","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1990/ra_6831_1990.html","fetchedAt":"2026-10-06","articleCount":59,"structureMode":"ARTICLE","title":{"zh":"1990年总拨款法","en":"General Appropriations Act of 1990","orig":"General Appropriations Act of 1990 An Act Appropriating Funds for the Operation of the Government of the Republic of the Philippines From January One to December Thirty-One, Nineteen Hundred and Ninety, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6831","issuingBody":"Congress of the Philippines","promulgatedDate":"1990-01-04","completenessNote":"全文，共 59 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1990/ra_6831_1990.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 63 条，缺 23、27、28、29、35）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。 源文存在同号重出的条款（第 22 条）：该处官方页面确有两段均标同一 Section 号，本库照录其 `no` 值（不改动官方编号），条文 `id` 以 `_2`「_3」后缀保证唯一。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5327-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Appropriation of Funds. The following sums, or so much thereof as may be necessary, are hereby appropriated out of any, funds in the National Treasury of the Philippines not otherwise appropriated, for the operation of tlie Government of the Republic of the Philippines from January one to December thirty-one, nineteen hundred and ninety except where otherwise specifically provided herein:\nI. CONGRESS OF THE PHILIPPINES\nII. OFFICE OF THE PRESIDENT\nIII. OFFICE OF THE VICE - PRESIDENT\nV. DEPARTMENT OF AGRICULTURE\nVI. DEPARTMENT OF BUDGET AND MANAGEMENT\nVII. DEPARTMENT OF EDUCATION, CULTURE AND SPORTS\nVIII. STATE UNIVERSITIES AND COLLEGES\nIX. DEPARTMENT OF ENVIRONMENT AND NATURAL RESOURCES\nX. DEPARTMENT OF FINANCES\nXI. DEPARTMENT OF FOREIGN AFFAIRS\nXII. DEPARTMENT OF HEALTH\nXIII. DEPARTMENT OF JUSTICE\nXIV. DEPARTMENT OF LABOR AND EMPLOYMENT\nXV. DEPARTMENT OF LOCAL GOVERNMENT\nXVI. DEPARTMENT OF NATIONAL DEFENSE\nXVII. DEPARTMENT OF PUBLIC WORKS AND HIGHWAYS\nXVIII. DEPARTMENT OF SCIENCE AND TECHNOLOGY\nXIX. DEPARTMENT OF SOCIAL WELFARE AND DEVELOPMENT\nXX. DEPARTMENT OF TOURISM\nXXI. DEPARTMENT OF TRADE AND INDUSTRY\nXXII. DEPARTMENT OF TRANSPORTATION AND COMMUNICATIONS\nXXIII. NATIONAL ECONOMIC AND DEVELOPMENT AUTHORITY\nXXIV. NATIONAL STATISTICAL COORDINATION BOARD\nXXV. OFFICE OF THE PRESS SECRETARY\nXXVI. OTHER EXECUTIVE OFFICES\nXXVII. THE JUDICIARY\nXXVIII. CONSTITUTIONAL COMMISSIONS\nXXIX. OFFICE OF THE OMBUDSMAN\nXXX. OFFICE OF THE SPECIAL PROSECUTOR\nXXXI. COMMISSION ON HUMAN RIGHTS\nXXXII. AUTONOMOUS REGIONS\nXXXIII. BUDGETARY SUPPORT TO GOVERNMENT CORPORATIONS\nXXXIV. NATIONAL ASSISTANCE TO LOCAL GOVERNMENT UNITS\nXXXV. CALAMITY FUND\nXXXVI. MISCELLANEOUS PERSONNEL BENEFITS FUND\nXXXVII. CONTINGENT FUND\nXXXVIII. ECONOMIC SUPPORT FUND\nXXXIX. FOREIGN ASSISTED PROJECTS SUPPORT FUND\nXL. GENERAL FUND ADJUSTMENTS\nXLI. INTERNATIONAL COMMITMENTS FUND\nXLII. PROPERTY REPLACEMENT FUND\nXLIII. SUPPLEMENTAL MILITARY/PC-INP SUBSISTENCE FUND\nXLIV. COUNTRYWIDE DEVELOPMENT FUND\nGENERAL PROVISIONS"}},{"id":"PH-H5327-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Fees, Charged and Assessments. All fees, charges, assessments, and other receipts or revenues collected by departments, bureaus, offices or agencies in the exercise of their functions, at such rates as are now or may be approved by the Secretary concerned, shall be deposited with the National Treasury and shall accrue to the General Fund pursuant to Section 50 of P.D. No. 1177 (Sec. 44 of Book VI, E.O. No. 292) and Section of B.P. Big. 325: PROVIDED , That certain receipts nay be recorded as income of Special Fund, Fiduciary or Trust Fund, or fund other than the General Fund, when authorized by law and following such rules and regulations as may be by the Permanent Corrmittee created under Section 51 of P.D. No. 1177 (Sec. 45 of Book VI, E.O. No. 292): PROVIDED, FURTHER , That all revenues or income accruing to special accounts in the General Fund may be made available for expenditure, subject to the Special Provision in this Act for the agencies concerned and to Special Budgets required under Section 40 of P.D. No. 1177 (Sec. 35 of Book VI, E.O. No. 292): AND PROVIDED, FURTHERMORE , That whenever practicable and taking into account the cost reduction program of the government when an agency contracts with another government office for fabrication of furniture or equipment or for computer, printing or other services, the agency rendering such services may assess the requesting agency for the cost of production and services rendered and may utilize the proceeds thereof subject to Section 40 of P.D. No. 1177 (Sec. 35 of Book VI, E.O. No. 292), except is otherwise provided in this Act: AND PROVIDED, FINALLY , That the schedule of fees, charges and assessments collectible by any government agency including government-owned and/or controlled corporations, shall be posted in big bold characters in conspicuous place in said government agency or corporations including its branches or extension, offices and that the updating and continuous display of said schedule shall be the responsibility of the head of the agency or corporation concerned."}},{"id":"PH-H5327-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Revolving Fund. Revolving funds shall be established and maintained only in cases where said funds are expressly created and authorized by law Revolving funds already in existence shall continue their operations.\nReceipts derived from business-type activities of departments, bureaus, offices or agencies which are authorized by law to be constituted into Revolving Fund shall be separately recorded and deposited in an authorized government depository bank, and may be made available for operational expenses of the said activity, of the agency concerned, subject to the conditions prescribed under the special provision of the agency concerned and the rules and regulations as may be prescribed by the aforementioned Permanent Committee, The Revolving Fund shall be considered self-perpetuating and self-liquidating and all obligations or expenditures incurred by virtue of said business-type activities shall be charged against the Revolving Fund: PROVIDED , That interest and other income earned shall be deposited with the National Treasury and shall accrue to the General Fund pursuant to Section 65 of P.D. No. 1445 and Section 29 (1) of Article VI of the Constitution.\nThe agency concerned shall submit to the Department of Budget and Management and to Congress quarterly report of the income from this Fund and quarterly report of expenditure. In case of failure to sulxnit said requirements, no withdrawal in the subsequent quarter shall be allowed except upon certification of the Department of Budget and Management that said report was submitted."}},{"id":"PH-H5327-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Trust Receipts. Receipts -from non-tax sources authorised by law for specific purposes which are collected/received by government office or agency acting as trustee, agent or administrator, or which have been received as guaranty for the fulfillment of an obligation, and all other collections classified by law or regulations as trust receipts shall be treated as trust liability of the agency concerned and deposited in an authorized government depository bank or in the National Treasury, as the case may be, subject to the conditions prescribed under the Special Provisions of the agency concerned and to the rules and regulations as determined by the Permanent Corrmittee created under Section 51 of P.D. No. 1177 (Sec. 45 of Book VI, E.O. No. 292). Pa.vment out of such funds shall be rrade in accordance with the purpose for which the fund is created and subject to accounting and auditing regulations: PROVIDED , That deposits in authorized government depository banks shall be withdrawable, subject to existing budget, accounting and auditing rules and regulations without the need for issuance of Funding Warrant: PROVIDED, FURTHER, That' if the amount is deposited in savings account, the interest shall accrue to the General Fund and shall be remitted to the National Treasury at the end of each quarter."}},{"id":"PH-H5327-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Seminar and Gonference Fees. Departments, bureaus, offices or agencies which conduct training programs approved jointly by the Department of Budget and Management and the Civil Service Commission are authorized to collect seminar and conference fees from government and private agency participants at such standard rates as the Department of Budget and Management and \"the Civil Service Commission shall deem appropriate. The proceeds derived from such seminars or conferences may be ad available for the conduct of such semjanars and conferences subject to pertinent budget, accounting and auditing rules and regulations: PROVIDED , That any excess therefrom shall be remitted to the National Treasury: PROVIDED, FURTHER , That upon the conclusion of the seminar or conference, the office authorized to conduct the sane shall submit -to the Department of Budget and Management a report of the income realized and of the expenses incurred: PROVIDED. FINALLY, That no appropriation authorized in this Act shall be used \"to support or. augment expenses for seminars or conferences."}},{"id":"PH-H5327-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Sale of Non-Serviceable Obsolete and Other Unnecessary Equipment. Departments bureaus, offices or agencies are hereby authorized to sell non-serviceable obsolete, and other unnecessary equipmen'ts.\nFifty percent (50%) of the proceeds from the sale of equimpment of the agency shall be deemed automatically appropriated for the purchase of new ones except cars, vans and the like and for the repair or rehabilitation of existing vital equipment for which no fund has been provided in this Act."}},{"id":"PH-H5327-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Sale of Products. Departmen'ts bureaus, offices or agencies are hereby authorized -to sell products of agricultural, industrial or other projects, including publications. The proceeds derived therefrom shall be deposi'ted with the National Treasury and shall accrue to the General Fund, pursuant to Section 50 of P.D. No. 1177 (Sec. 44 of Book VI, E.O. No'. 292), unless o'therwise provided by law or by Special Provision in this Act."}},{"id":"PH-H5327-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Donations. Departmen'ts, bureaus, offices or agencies are authorized \"to accept donations, contributions, grants, bequests or gifts, in cash or in kind, from foreign governments, international and local agencies, private entities or individuals for purposes relevant to their functions. Such receip'ts shall be accounted for in \"the books of the government and shall be subject to pertinent accounting and auditing rules and regulations.\nSuch donations, whether in cash or in kind, shall be deemed automatically appropriated for the purposes specified by the donor. Receipts from cash sale of donated commodities shall be remitted to the National Treasury and recorded as a Special Account in the General Fund and shall be released only to the extent of actual receipts as certified by the Bureau of the Treasury and used or expended as specified by the donor, subject to Section 40 of P.D. No. 1177 (Sec. 32 of Book VI, E.O. No. 292). The agency concerned shall submit to the Department of Budget and Management and to the amounts released. Whenever a donation is made, the recepient office or aganecy shall notify the Department of Budget and Management which shall issue the corresponding advice of allotment.\nThe rules and regulations to supplement this Section shall be issued jointly by the Department of Budget and Management and the Department of Finance."}},{"id":"PH-H5327-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Expenditures Funded from Borrowings. The amoun-ts appropriated in this Act and funded from local or foreign borrowings' shall he released in accordance with loan drawdowns or in the manner stipulated in the financing agreement concerned, subject to Section 40 of P.D. No. 1177 (Sec. 35 of Book VI, E.O. No. 292)."}},{"id":"PH-H5327-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Foreign Purchases and Other Importations. Purchases under foreign military sales agreemen'ts, heavy equipment imports for infrastructure projects and other importations of agencies which are financed by foreign borrowings or by Central Bank consolidated borrowing programs shall be subject to the requirement of a certification of availability of appropriations released for the purpose, to the requiremen'ts of LOI No. 880 and to applicable laws, rules and regulations."}},{"id":"PH-H5327-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Loan Agreements. Departments, bureaus, offices or agencies, including government-owned and/or controlled corporations shall in no case enter into foreign or domestic loan agreements, whether in cash or in kind, except upon concurrence of the Secretary of Budget and Management with respect to peso requirements and irriplications on expenditure ceilings and prior approval of the President of the Philippines, with the prior concurrence of the Monetary Board, subject to such limitations as nay provided by law: PROVIDED , That the Monetary Board shall, within thirty days from the end of every quarter of the calendar year, submit to the Congress of the Philippines report of its decisions on applications for loans to be contracted or guaranteed by the government or government-owned and/or controlled corporations which have the effect of increasing the foreign debt. Loans shall not be contracted by agencies of the national government unless the full amount of the loan is covered by an Obligational Authority issued by the Secretary of Budget and Management.\nFor this purpose, the budgetary implications of foreign-assisted projects shall be explicitly considered by the Secretary of Budget and Management and the office or agency concerned at the time of project design and financing negotiations'. The project study shall specify the cash flow requirements of the project among others, for: (a) payment of principal and interest; (b) peso component of capital costs and project preparation; (c) infrastructure and support facilities needed to be directly financed by government; (d) operating and other expenditures which will be ultimately required for general fund support when the project is implemented; and (e) peso requirements needed as counterpart."}},{"id":"PH-H5327-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Performance Bonds and Deposits. Performance bonds and deposits filed or posted by private persons or entities with agencies of the government shall be deposited with an authorized government depository bank as trust liabilities and under the name of the agency concerned. Upon faithful performance of the undertaking or termination of the obligation for which the bond or deposit was required, any amount due shall be returned to the filing party and the office or agency concerned, withdrawable in accordance with accounting and auditing rules and regulations: PROVIDED, That any interest accruing on deposit accounts and aw forfeited amounts shall be recorded as income of the General Fund and shall be remitted to the National Treasury at the end of each quarter. This provision shall apply to bonds posted in cash, such as bidder's bond, guaranty bonds, bail bonds, judicial deposits for the benefit of clients, cash under litigation deposited in court or quasi-judicial bodies and other refundable and judicial bonds, and all bonds and deposits required by law, rules and regulations to be posted to ensure the faithful performance of an activity or undertaking.\nAUTHORIZED EXPENDITURES"}},{"id":"PH-H5327-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Restrictions on the Use of Appropriated Funds. The amounts released, particularly for but not limited to, petroleum, oil and lubricants as well as for water, illumination and power services, telephone and other comrunication services, rents, retirement gratuity and terminal leave requirements shall be disbursed solely for such items of expenditures in accordance with the Work and Financial Plan as approved by the Secretary of Budget and Management.\nThe use of funds in violation of this Section shall be null and void, and shall subject the erring officials and employees to disciplinary action under the provisions of Sections 49 and 87 of P.D. No. 1177 (Secs. 43 and 80 of Book VI, E.O. No. 292) and to appropriate criminal action under existing penal laws."}},{"id":"PH-H5327-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"National Internal Revenue Taxes, and Import Duties of National and Local Government Agencies. National internal revenue taxes and import duties payable hy national government agencies to the National Government as well as customs duties and for the importation of equipment by local government units, are deemed automatically appropriated. The amounts pertaining to such taxes and duties shall be considered as revenue and expenditure of the government.\nThe Department of Budget and Management and the Department of Finance shall, issue the implementing guidelines."}},{"id":"PH-H5327-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Expenditure Gooponents Except by act of the Congress of the Philippines, no change or modification shall be made in the expenditure items authorized in this Act and other appropriations laws unless in cases of augmentations from saving in appropriations as authorized under Section 25 (5) of Article VI of the Constitution."}},{"id":"PH-H5327-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Use of Savings. The President of the Philippines, the President of the benate, the Speaker of the House of Representatives, the Chief Justice of the Supreme Court of the Heads of Constitutional Corrmissions under-Article IX of the Constitution, and the ftnbudsman are hereby authorized to augment any item in this Act for their offices from savings in other items of their respective appropriations: PROVIDED, That no item of appropriation recommended by the President in the budget submitted to Congress Pursuant to Article VII, Section 22 of the Constitution which has been disapproved or reduced by Congress shall be restored or increased by the use of appropriations 'authorized for other purposes in this Act by augmentation. Any item of appropriation for any purpose recommended by the President in the budget shall be deemed to have been disapproved by Congress if no corresponding appropriation for the specific purpose is provided in this Act."}},{"id":"PH-H5327-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Priority in the Use of Savings. In the use of savings priority shall given to the augmen'tation of the amounts set aiside for salary standardization, bonus and retirement and terminal leave benefits in the order listed."}},{"id":"PH-H5327-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Meaning of Savings and Augmentation. Savings refer to portions or balances of any programmed appropriation free of any obligation or encumbrance still available after the satisfactory completion or unavoidable discontinuance or abandonment of the work, activity or purpose for which \"the appropriation is authorized, or arising from unpaid compensation and related costs pertaining to vacant positions and leaves of absence without pay.\nAugmented implied the existence in this Act of an item, project, activity or purpose with an appropriation which upon implementation or subsequent evaluation of needed resources is determined to be deficient. In no case, therefore, shall a non-existence item, project activity, purpose or object of expenditure be funded by augmentation from savings or by the use of appropriations authorized otherwise in this Act."}},{"id":"PH-H5327-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Information Outlay. The appropriations pertaining to information activities of various departments, bureaus, offices or agencies shall be released upon prcsen-tation of an appropriate program of activities prepared by their respective Heads copies of which shall be furnished the Congress of the Philippines"}},{"id":"PH-H5327-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Purchase of Supplies, Materials and Equipment Spare Parts. The stock on hand of supplies, materials and equipment spare psarts to be acquired through ordinary purchase out of appropriations herein provided shall at no time exceed normal three-month requirements subject to pertinent rules and regulations issued by competent authority: PROVIDED, That heads of departments bureaus, offices or agencies or otlier instrumentalities of the government may approve the build-up of stocks on hand critical supplies and materials as defined or specified by the Department of Budget and Management in anticipation of cost increases of requirement of national emergency, or of an impending shortage in the items concerned, specifying maximum quatities of individual items. Unless o'therwise approved by the President, upon the joint recommendation of the Secretary concerned and the Chairman of the Commission on Audit, these stocks shall not exceed one year's need."}},{"id":"PH-H5327-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Emergency Purchases. Unless otherwise provided in this Act, departments bureaus, offices or agencies of the national government are authorized to make emergency purchases of supplies, materials and spare parts of motor transport equipment that are urgently needed for the repair of ambulances, motor vehicles, vessels and aircraf'ts or to meet an emergency which may involve the loss of, or danger to, life and/or property or are 'to be used in connection with a project or activity which cannot be delayed without causing detriment to the public service, in a monthly amount not exceeding four percent of the annual agency expenditure program for supplies and materials out of the appropriations allotted for maintenance and other operating expenses of the agency concerned, except as may be authorized by the President of the Philippines upon the joint recommendation of the Department of Budget and Management and the Commission on Audit."}},{"id":"PH-H5327-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Cultural and Athletic Activities. An amount not exceeding ₱45,000 per annum out of the appropriations alloted for maintenance and toher operating expenses for each department bureau, office or agency, and ₱15,000 for each regional office of each regionalized department, bureau, office or agency, may be used for cultural anf athletic activities, including purchase of uniforms at not more than ₱500"}},{"id":"PH-H5327-A22_2","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Cultural and Athletic Activities. An amount not exceeding ₱45,000 per annum out of the appropriations allotted for maintenance and other operating expenses for each department bureau, office or agency, and ₱15,000 for each regional office of each regionalized department, bureau, office or agency, may be used for cultural and athletic activities, including purchase of uniforms at not more than ₱500 for each participant, and for supplies and necessary expenses for said activities. The amounts fixed in this Section constitute the allowable maximum to be expended by any department bureau, office or agency for its cultural and athletic activities, except as otherwise approved by the President of the Philippines: PROVIDED , That these amounts may be pooled by the Secretary concerned into one fund, programmed and controlled to best serve the needs of the department and all the offices, bureaus and agencies therein.\nFor purposes of this Section, the term “office or agency” shall be so construed refer only to departments and bureaus, and the regular government offices or agencies under them. Section 23. Contracting Multi-Year Projects. In the implementation of multi-year projects, no agency shall enter into a contract without a Forward Obligational Authority issued by the Department of Budget and Management for the purpose.\nNotwithstanding the issuance of the Forward Obligational Authority, the obligation to be incurred in any given calendar year, shall in no case exceed the amount programmed for implementation of the multi-year projects during said Calendar Year."}},{"id":"PH-H5327-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Extraordinary and Miscellaneous Expenses. Appropriations herein authorized may be used for extraordinary expenses not exceeding:\na. ₱120,000 for each Secretary or equivalent;\nb. ₱40,000 for each Undersecretary or equivalent;\nc. ₱16,000 for each Assistant Secretary, head of bureau or organization of equal rank to bureau and for each Department Regional Director; and\nd. ₱8,000 for each Bureau Regional Director.\nIn addition, miscellaneous expenses not exceeding ₱24,000 for each of the offices under the above named officials are herein authorized.\nFor purposes of the Section, representation and miscellaneous expenses shall include, but shall not be limited to, expenses incurred for:\na. meetings seminars and conferences\nb. official entertainment;\nc. public relations;\nd. educational, athletic and cultural activities;\ne. contributions to civic or charitable institutions;\nf. membership in government associations;\ng. membership in national professional organizations duly accredited by the Professional Regulation Commission;\nh. membership in the Integrated Bar of the Philippines;\ni. subscription to professional technical journals and informative magazines, library books and materials;\nj. office equipment and supplies; and\nk. other similar expenses not supported by the regular budget allocation.\nNo portion of the amounts authorized herein shall be used for salaries, wages, allowances, intelligence and confidential expenses.\nThese expenditures shall be subject to the accounting and auditing rules and regulations."}},{"id":"PH-H5327-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Release of Intelligence and Confidential Funds. No amount appropriated in this Act shall be released or disbursed for confidential and intelligence activities unless specifically identified and authorized as such intelligence or confidential fund in this Act.\nIntelligence and confidential funds provided for in the budgets of departments, bureaus, offices or agencies of the national government, including amounts from savings authorized by Special Provisions to be used for intelligence and counter-intelligence activities, shall be released only upon approval of the President of the Philippines.\nAll departments, bureaus and offices shall submit to the Secretary of the Department of Budget and Management, the Chairman of the House Committee on Appropriations and the Chairman of the Senate Committee on Finance, a quarterly report on the utilization of intelligence and confidential funds."}},{"id":"PH-H5327-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"Release of Funds. Any provision of law to the contrary notwithstanding, the appropriations authorized for the Judiciary, Congress of the Philippines, the Commission on Human Rights, the Office of the Ombudsman. The Civil Service Commission, the Commission on Audit and the Commission on Elections in the Act shall be automatically and regularly released in accordance with a Work and Financial Plan.\nSection 27 . Disbursement of Funds. All appropriated funds shall be disbursed only through the National Treasury and/or originally-chartered government-owned or controlled banks.\nSection 28 . Funding Contracts and Future Payment of Contractual Obligations. Notwithstanding the availability of deferred payment terms, departments, bureaus, offices or agencies concerned, before entering into contracts involving the expenditure of public funds, including contracts for services or consultancy, contracts of lease, equipment rental, construction of partitions or improvements in leased buildings, or certification of availability of funds for the purpose from the agency Chief Accountant, subject to applicable rules and regulations as may be issued by the Department of Budget and Management and to Sections 46 and 64 of P.D No. 1177 (Secs. 40 and 58 of Book VI E.O No. 292) : PROVIDED , That the certification of availability of funds sufficient to cover the cost of the contracted activities shall be contained in and made part of the contract duly signed by the Chief Accountant of the contracting agency, as provided for by LOI No. 968. Departments, bureaus, offices or agencies, before entering into contracts for delivery of goods or services against future contracted amount for such goods or services out of the agency’s appropriations. No contracts shall be entered into nor work undertaken without such certification of funds availability.\nSection 29 . Service Contracts. Departments, bureaus, offices or agencies of the national government are hereby authorized to enter into contracts with private firms; and non-governmental organizations for services related or incidental to their respective functions and operations, through public bidding or negotiated contracts, whenever it is impractical or more expensive for the government to directly undertake such flections and operations, subject to accounting and auditing rules and regulations: PROVIDED , That the execution of the service contracts shall not operate to automatically abolish or render vacant any existing occupied position in the contracting office or agency.\nPERSONAL SERVICES BENEFITS"}},{"id":"PH-H5327-A30","no":30,"noLabel":{"en":"Section 30."},"text":{"en":"Health Financial Assistance Program. Subject to the enactment of a law for the purpose. The amount necessary to cover increases authorized in medicare benefits for GSIS Medicare beneficiaries shall be taken form budgetary savings of national government agencies. For this purpose the Department of Budget and Management is hereby authorized to set aside the amount necessary to cover the FYI 1990 Financial Assistance Program form the appropriations provided in this Act for the current operating expenses of the national government concerned. In subsequent years, the requirement for the Health Financial Assistance Program shall be included in the Philippine Medical Care Commission and the Government Services Insurance System shall jointly promulgate the necessary rules and regulations to implement this Section"}},{"id":"PH-H5327-A31","no":31,"noLabel":{"en":"Section 31."},"text":{"en":"Funding of Personnel Benefits. The personnel benefits costs of government officials and employees shall be charged against the respective funds from which their compensations are paid.\nAll authorized supplement or additional compensation, fringe benefits and other personal services costs of officials and employees whose salaries are drawn form special accounts or special funds, such as salary increases and adjustments, merit increases, incentive and service fees, vacation and sick leaves, retirement and life insurance premiums, compensations insurance premiums, health insurance (Medicare) premiums, HDMF contributions, hospitalization and medical benefits, scholarship and educational benefits, training and seminar expenses, all kinds of allowances, whether privileges authorized by law, including the payment of retirement gratuities, separation pay and terminal leave benefits, shall be charged against the corresponding fund from which their basic salaries are drawn and in no case shall such personnel benefits costs be charged against the General Fund of the national government.\nOfficials and employees on detail with other offices, including the representatives and support personnel of auditing units assigned to serve other offices or agencies, shall be paid their salaries, emoluments, allowances and the foregoing supplemental compensation, fringe benefits and other personal services costs from the appropriations of their parent agencies, and in no case shall such be charged against the appropriations of the agencies where they are assigned or detailed, except when authorized by law."}},{"id":"PH-H5327-A32","no":32,"noLabel":{"en":"Section 32."},"text":{"en":"Personnel Benefits Fund. The Employees Compensation Insurance Premium Fund, the National Government Contributions to the Health Insurance (Medicare) Fund and the Employers Share in the Home Development Mutual Fund (PAG-IBIG) shall be released directly by the Department of Budget and Management to the Government Service Insurance System and the Home Development Mutual Fund.\nPayment of amelioration benefits to cover the year-end bonus and cash gift provided under Republic Act No. 6686 shall be released to the department, bureau, office or agency concerned.\nSavings generated in one department, bureau, office or agency shall be used to augment deficiencies in other departments, bureaus, offices or agencies."}},{"id":"PH-H5327-A33","no":33,"noLabel":{"en":"Section 33."},"text":{"en":"Appropriations for Salary Standardization. The appropriations in this Act for salary standardization, cost of living and other allowances authorized, in the respective budgets of departments, bureaus, offices and agencies shall be used solely for the purpose of salary standardization as provided in Republic Act No. 6758.\nSavings generated in one department, bureau, office or agency shall be used to augment deficiencies in other departments, bureaus, offices or agencies."}},{"id":"PH-H5327-A34","no":34,"noLabel":{"en":"Section 34."},"text":{"en":"Representation and Transportation Allowances. The following officials and those of equivalent rank as may be determined by the Department of Budget and Management are hereby granted monthly commutable representation and transportation allowances payable from the programmed appropriations provided for their respective offices, not exceeding the rates indicated below, which shall apply to each type of allowance\na. At ₱2,500 for Secretaries or equivalent;\nb. At ₱1,700 for Department Undersecretaries or equivalent;\nc. At ₱1,500 for Assistant Secretaries, Bureau Directors and Department Regional Directors or equivalent;\nd. At ₱1,400 for Assistant Bureau Directors, Department Assistant Regional Directors, Bureau Regional Directors, Department Service Chiefs or equivalent;\ne. At ₱1,200 for Assistant Bureau Regional Directors or equivalent;\nf. At ₱1,100 for Chiefs of Divisions, identified as such in the Personal Services Itemization. he transportation allowance herein authorized shall not be granted to officials who are assigned a government vehicle or use government motor transportation, except as may be approved by the President of the Philippines. Unless otherwise provided by law, no amount appropriated in. this Act shall be used to pay for representation and/or transportation allowances, whether commutable or reimbursable which exceed the rates authorized under this Section Previous administrative authorizations not consistent with the rates and conditions herein specified shall no -longer be Valid and payment shall not be allowed.\nAllowances of those officials who are receiving salaries from special accounts or special funds shall be charged against the corresponding fund from which their salaries are charged. Officials on detail with other offices, including officials of the Commission on Audit assigned to serve other offices or agencies, shall be paid the allowance herein authorized from the appropriations of their parent agencies.\nSection 35 . Official Vehicles and Transport. Government motor transportation may the used by the following officials, including those who may be specifically authorized by the President of the Philippines, the President of the Senate with respect to the Senate, and the Speaker, with respect to the House of Representatives, with costs chargeable to the appropriations authorized for their respective offices:\na. The President of the Philippines;\nb. The Vice-President;\nc. The President of the Senate;\nd. The Speaker of the House of Representatives;\ne. The Chief Justice of the Supreme Court;\nf. The Secretaries, Undersecretaries and officials of equivalent rank;\ng. The Presiding Justice of the Court of Appeals;\nh. Ambassadors, Ministers Plenipotentiary and Consuls in charge of Consulates, in their respective stations abroad;\ni. The Chief of Staff, the Vice-Chief of Staff, and the Commanding Generals of the major services of the Armed Forces of the Philippines; and\nj. The Heads of Constitutional Commissions."}},{"id":"PH-H5327-A36","no":36,"noLabel":{"en":"Section 36."},"text":{"en":"Uniform and Clothing Allowance. The appropriations herein provided for each department, bureau, office or agency may be used for uniform and clothing allowance of employees at not more than PI,000 each per annum. Savings in the appropriations for each department, bureau or office may be used for this purpose where no amount is specifically appropriated in this Act."}},{"id":"PH-H5327-A37","no":37,"noLabel":{"en":"Section 37."},"text":{"en":"Hazard Duty Pay. Upon recommendation of the Department Head and approval of the Department of Budget and Management, hazard pay may be allowed to officials and employees who are actually assigned in hardship or difficult areas, strife-torn or embattled areas, distressed or isolated stations, prison camps, mental hospitals radiation-exposed clinics or laboratories or disease-infested areas or in areas declared under state of calamity or emergency for the duration thereof which expose them to great danger, contagion, radiation, volcanic activity/eruption, occupational risks or perils to life, chargeable to savings in the appropriations of the department/agency concerned, which shall not be less than P50 nor more than P150 each per month, except in cases where the rates are specifically provided for under special laws, charters or enabling acts, in which case such rates shall where more incentives are needed to attract applicants, in which case the augmented at rates to be determined by the Department Heads as may be PROVIDED, That hazard pay by reason of strife-tom or embattled areas shall be subject to the certification issued by the Secretary of National Defense and the rates thereof Stoll be determined by the Secretary of Budget and Management on the basis of the area classification certified by the Secretary of National Defense, The Secretary of Budget and Management and the Secretary of National Defense shall review from time to time authorizations for the payment of hazard duty pay in strife-tom and embattled areas earlier issued and shall terminate such authorizations in areas where conditions no longer justify the continuation of hazard duty pay."}},{"id":"PH-H5327-A38","no":38,"noLabel":{"en":"Section 38."},"text":{"en":"Honoraria. Departments, bureaus offices or agencies are authorized to use their respective appropriations for payment of honoraria as compensation for services rendered by researchers, experts and specialists who are acknowledged authorities in their field of specialization and military personnel who are rendering security service to the Congress of the Philippines, including its Committees, at such rates as the Department of Budget and Management may authorize, unless otherwise specifically provided by law."}},{"id":"PH-H5327-A39","no":39,"noLabel":{"en":"Section 39."},"text":{"en":"Authorized Deductions, Incentive and Service Fees. Deductions from salaries, emoluments or other benefits accruing to any government employee may be allowed for the payment of obligations due or owing to government lending institutions such as government banks, the Government Service Insurance System or a savings and loans association, and those organized for, and managed by, government employees. Deductions under Section 21 of R.A. No. 4670, otherwise known as the Magna Carta for Public School Teachers. may be allowed, including such deductions representing amortizations arising from educational loan for tuition fees, reasonable amount for textbooks and other school obligations granted by insurance companies duly licensed by the Insurance Commission; PROVIDED , That such deductions shall not reduce the employee’s take home pay to an amount lower than one thousand pesos, after deducting all other statutory deductions: PROVIDED FURTHER , That the agencies and offices with existing deduction arrangements with private lenders, shall continue such deductions until the credits/loans outstanding or the premiums of the policies in force at the date of passage of this Act shall have been fully paid.\nAny surplus of service fees deposited with the National Treasury pursuant to the provisions of the second paragraph hereof, shall form part of a provident fund to be established by the agency in favor of all its employees, which shall be available to employees for emergency needs, school and educational loans, hospitalization loans, minor but immediate need of repair of houses and other similar circumstances. This fund shall be administered pursuant to a set of uniform rules and regulations which the Office of the President shall promulgate."}},{"id":"PH-H5327-A40","no":40,"noLabel":{"en":"Section 40."},"text":{"en":"Special Counsel Allowance. Lawyer-personnel in the legal staffs of departments, bureaus, offices or agencies of the national government appearing in Court as special counsel in collaboration1 with the Solicitor General or Fiscals concerned are hereby authorized an allowance of P150 for each appearance, chargeable to savings in the appropriations allotted for personal services of their respective offices, but not exceeding P900 a month."}},{"id":"PH-H5327-A41","no":41,"noLabel":{"en":"Section 41."},"text":{"en":"Quarters Allowance. Except as may be authorized by law, government officials and employees who, by virtue of their positions, are furnished free quarters or are charged only a nominal rate in government-owned buildings, such as dormitories or. living quarters in hospitals, state colleges, universities and schools, foreign posts and elsewhere, shall forfeit entitlement to any quarters allowance. In cases where portions of rented private buildings are authorized to be utilized for officials' quarters, the excess of rental cost over the quarters allowance of the officials shall be borne by Llio- officials or employees concerned. Those who enjoy free quarters in government-owned or rented buildings but who are not entitled to quarters privileges, shall be charged the corresponding cost of rentals therefor. Unless fixed by law or regulations, the rate of quarters allowance or rental, as the case may be, shall be determined by the Department of Budget and Management."}},{"id":"PH-H5327-A42","no":42,"noLabel":{"en":"Section 42."},"text":{"en":"Compensation of Contractual Personnel. Heads of departments, bureaus, offices or agencies, when authorized in their respective appropriations as provided in this Act, may hire, consultants, experts and other contractual personnel to perform specific vital activities or services which cannot be provided by the regular staff of the agency, limited to such period when their services are reasonably required and to activities that shall have a definite expected output. Such contractual personnel may be paid compensation inclusive of fees, honoraria, per diems compensation and allowances not exceeding 120 percent of the minimum salary of an equivalent position in the National Classification and Compensation Plan, except as may be authorized by the Department of Budget and Management in the following instances: (a) when the consultant or expert is an acknowledged authority in his field of specialization, and (b) where the consultant or expert is hired to perform a specific activity or service that requires technical skill and expertise which local labor force cannot provide, or if such expertise is available, the supply is limited: PROVIDED , That in no case shall such compensation exceed the salary of his immediate superior, except as may be otherwise approved jointly by the Civil Service Commission and the Department of Budget and Management."}},{"id":"PH-H5327-A43","no":43,"noLabel":{"en":"Section 43."},"text":{"en":"Use of Appropriations for Retirement Gratuity and Terminal Leave. Release of appropriations authorized in this Act to cover retirement gratuity benefit shall be made on the basis of the Work and Financial Plan of offices and agencies as approved by the Department of Budget and Management. In no case shall payment be made except on the basis of creditable services as computed by the Government Service Insurance System in accordance with the provisions of existing retirement laws. Unless otherwise authorized by law, no amount appropriated in this Act shall be used for payment of retirement gratuity under the provisions of Section 12(c) of C.A. No. 186, as amended by R.A. No. 1616 and terminal leave benefits of retiring officials and employees which include in the computation thereof additional compensation as defined under retirement laws such as bonuses, per diems, allowances and overtime pay, or salary, pay or compensation given in addition to the base pay of the position or rank as fixed by law or regulation.\nSavings generated in one department, bureau, office or agency shall be used to augment deficiencies in other departments, bureaus, offices or agencies.\nThe rules and regulations to implement this Section shall be issued jointly by the Department of Budget and Management, the Government Service Insurance System and the Civil Service Commission."}},{"id":"PH-H5327-A44","no":44,"noLabel":{"en":"Section 44."},"text":{"en":"Unauthorized Pre-Retirement Promotions and Salary Increases . No portion of the appropriations provided in this Act shall be used for automatic promotions or for salary increases and adjustments granted to retiring officials and employees, which are not authorized by law and duly formalized in a National Compensation Circular.\nThe rules and regulations to implement this Section shall be issued jointly by the Civil Service Commission and the Department of Budget and Management."}},{"id":"PH-H5327-A45","no":45,"noLabel":{"en":"Section 45."},"text":{"en":"Abolition of Positions. The positions, vacated resulting from the early retirement or separation of personnel under Republic Act No. 6683 shall be abolished unless the head of the office or agency, with the approval of the President in the case of the Executive Department, the Chief Justice in the case of the Judiciary, the Senate President in the case of the Senate or the Speaker in the case of the House of Representatives, the Chairman in the case of the Constitutional Commissions, certified within the period of sixty (60) days from the time of approval of the application for retirement or separation that the exigencies of the service required their retention."}},{"id":"PH-H5327-A46","no":46,"noLabel":{"en":"Section 46."},"text":{"en":"Personal Liability of Officials for Payment of Unauthorized Personal Services Cost. No official or employee of the National Government, including those of government-own and/or controlled corporations, shall be paid any unauthorized personal services benefits charged against the appropriations in this Act, other appropriations laws or income of the government.\nThe payment of any unauthorized personal services benefits in violation of this Section is null and void. The erring officials and employees shall be subject to disciplinary action under the provisions of Sections 49 and 87 of P.D. No. 1177 (Secs. 43 and 80 of Book VI, E.O. No. 292) and to appropriate criminal action under existing penal laws.\nADMINISTRATIVE PROCEDURES"}},{"id":"PH-H5327-A47","no":47,"noLabel":{"en":"Section 47."},"text":{"en":"Training Programs. Departments, bureaus, offices or agencies shall review and formulate their training programs to make the same responsive to the organizational needs and manpower requirements of agencies and the need to train personnel in skills and attitudes. Such training programs shall be consistent with the rules and relations issued by the Training Coordination Committee created under LOI No. 754, which shall review and evaluate training activities."}},{"id":"PH-H5327-A48","no":48,"noLabel":{"en":"Section 48."},"text":{"en":"Direct Release of Blinds to Regional Offices. Funds allotted for regional offices but included in the budgets of their central offices or which are specifically allocated for the different regions shall be released directly to said regional offices. Imposition of any retention or deduction as reserves shall not be allowed except as may be authorized by the Department of Budget and Management. For this purpose, the Department of Budget and Management shall identify by region the expenditure programs of agencies in the national government budget and shall release funds intended for them in accordance with the approved regional distribution of expenditures specifying the region- of destination. Copies of fund releases to -the said regional offices shall be furnished the House Committee on Appropriations and the Senate Committee on Finance."}},{"id":"PH-H5327-A49","no":49,"noLabel":{"en":"Section 49."},"text":{"en":"Prohibition Against Deduction/Retention of Allotment. Fund releases from appropriations provided in this Act for any' function/project shall be transmitted intact or in full to the office or agency concerned and no retention or deduction as reserves or overhead shall be made, except as authorized by law or upon direction of the President of the Philippines. The Commission on Audit shall, ensure compliance with this provision to the extent that sub-allotments by departments and/or central agencies to their subordinate offices are in conformity with allocations in budgetary Advice of Allotments issued by the Department of Budget and Management."}},{"id":"PH-H5327-A50","no":50,"noLabel":{"en":"Section 50."},"text":{"en":"Work and Financial Plan. All departments, bureaus, offices and agencies, including government-owned and/or controlled corporations, shall submit their respective Work and Financial Plans as may be required by the Department of Budget and Management as the basis for the release of allotments, and funding warrants.\nThe Work and Financial Plan shall be prepared in accordance with the form and content as prescribed by the Secretary of Budget and Management.\nNo deviations shall be allowed from the approved Work and Financial Plan except upon prior approval of the Secretary of Budget and Management.\nAgencies, however, may augment an item of expenditure within Maintenance and Other Operating Expenses (MOOE) from savings in other items of MOOE not. exceeding twenty-five percent (25%) of the appropriated amount to be augmented."}},{"id":"PH-H5327-A51","no":51,"noLabel":{"en":"Section 51."},"text":{"en":"Submission of Corporate Operating Budgets and Financial Statements. All government-owned and/or controlled corporations shall submit through the Secretary of Budget and Management their respective corporate operating budgets for FY 1990 recommended by the Governing Board of the Corporations for consideration and final approval of the President of the Philippines. The corporate operating budgets shall be prepared following such procedure and guidelines issued by the Secretary of Budget and Management and shall be accompanied with financial statements and other reports as may be required."}},{"id":"PH-H5327-A52","no":52,"noLabel":{"en":"Section 52."},"text":{"en":"Corporations. Use of the Funds Allotted for Budgetary Support to (Government The amounts herein appropriated for budgetary support to government-owned and/or controlled corporations which are included under the budgets of the Department/Offices to which these are attached, may be used to support operating expenses, loans outlays and equity investments or trust funds to be administered by government-owned and/or controlled corporations: PROVIDED , That payment of salaries, allowances-and other benefits shall be in accordance with P.D. No. 985 and that retirement gratuities paid from this fund shall be computed in accordance with the rates, conditions and procedures prescribed under-existing retirement laws, rules and regulations: PROVIDED, FURTHER , That, in no case shall equity investments be used for salaries, allowances, retirement gratuities and other benefits: AND PROVIDED, FINALLY, That releases shall be subject to Section 40 of P.D. No. 1177 (Sec. 35 of Book VI, E.O. No. 292) and LOImp. No. 29."}},{"id":"PH-H5327-A53","no":53,"noLabel":{"en":"Section 53."},"text":{"en":"Fund Releases for Budgetary Support to Government Corporations. Funds herein appropriated for budgetary support to government-owned and/or controlled corporations shall be under the administration of the Department of Budget and Management. Said funds will be directly released to the recipient corporations through the of Treasury. All requests for fund releases for subsidies or capital investments to government corporations shall emanate from their respective Boards through the Departments to which they are attached."}},{"id":"PH-H5327-A54","no":54,"noLabel":{"en":"Section 54."},"text":{"en":"Offsets Against Budgetary Support and Conversion of Advances for Government Corporations. The appropriations herein authorized for budgetary support to government- corporations may be used by the Bureau of the Treasury for the corporate payments of the five percent (5%) dividend under Executive Order No. 518, as well as repayments for the loans relent to corporate obligations guaranteed by the Government of the Republic of the Philippines. If the total level of actual revenues at the end of 1989, liquid assets (i.e., cash and short term investments), bond investments and other fund sources of a government corporation' exceed the corresponding projections consistent with the formulation of the 1990 budgetary support program, then the excess may be deducted from the said program and may be reduced to the extent of such favorable effect. Furthermore, advances already made prior to January 1, 1990 for loan obligations shall be converted into equity or subsidy of the national government upon the recommendation of the Secretary of Finance. Such conversions are deemed appropriated and shall require the issuance of an Advice of Allotment."}},{"id":"PH-H5327-A55","no":55,"noLabel":{"en":"Section 55."},"text":{"en":"Submission of Quarterly Reports. Within 15 days after the end of each quarter, each department, bureau, office or agency shall submit a quarterly report to the House Committee on Appropriations and the Senate Committee on Finance, copy furnished the Department of Budget and Management, on their cumulative allotments, obligations incurred/liquidated, total disbursements, unliquidated obligations, unobligated and unexpended balances, and the results of expended appropriations.\nThe quarterly report shall include detailed statements on the disbursements and utilization of appropriations for the purchase of motor vehicles and equipment, capital investment outlays, as well as appropriations earmarked and released for rentals, travels, petroleum, oil and lubricants, water, illumination and power services, and telephone and other communication services."}},{"id":"PH-H5327-A56","no":56,"noLabel":{"en":"Section 56."},"text":{"en":"Unauthorized Organizational Changes. Unless otherwise created by law or directed by the President of the Philippines, no organizational unit or changes in key position in any department or agency shall be authorized in their respective organizational structures and be funded from appropriations provided by this Act."}},{"id":"PH-H5327-A57","no":57,"noLabel":{"en":"Section 57."},"text":{"en":"Implementation of Construction Projects. Construction projects funded from capital outlays authorized in this Act under the various departments, bureaus, offices or agencies of the national government, including the construction of buildings for state universities, colleges, schools, hospitals, sanitaria, health centers and health stations, roads and bridges, shall be implemented only in accordance with the appropriate standards and specifications for the planning, survey, design .and construction of the project as prescribed by the Department of' Public Works and Highways or the Department of Transportation and Communications, through either of said department’s as the case may be. In addition, land use and zoning guidelines as prescribed by existing laws, rules and regulations shall be strictly observed. In -the implementation of the construction projects. Sections 2, 3, 4, 5, 6, 7, 9, 10 and 12 of Executive Order No. 182, entitled \"Rationalizing Public Works Measures, Appropriating Funds for Public Works, and for Other Purposes\", and other legislations on public works shall be strictly complied with."}},{"id":"PH-H5327-A58","no":58,"noLabel":{"en":"Section 58."},"text":{"en":"''Realignment\" (Relocation) of Capital Outlays and Public Works Projects. The amount appropriated in this- Act for construction, replacement, rehabilitation and completion of school buildings, hospitals, sanitaria, health centers, clinics, herbal processing plant, warehouses, and health stations, as well as waterworks/supply and other public works projects under the FY 1990 infrastructure program in this Act may be \"realigned\" in cases of imbalanced allocation of projects within \"the district, duplication of projects, overlapping of funding source and similar cases: PROVIDED , That such \"realignment\" shall be made within -thirty (30) days after the approval of this Act except in cases of duplication of projects and overlapping of funding source: PROVIDED, FURTHER , That such \"realignment\" is within the congressional district for which the fund were originally allocated-ted: PROVIDED, FURTHERMORE, That the \"realignment\" shall be for projects within the same category and shall not exceed the -total amount originally allocated-ted for the congressional district: AND PROVIDED, FINALLY, That \"the \"realignment\" shall be made upon \"the initiative and consent of the representative of the district concerned and with -the concurrence of any one of the following: The. District Engineer, the Regional Director or Secretary of the Department concerned.\nThe Department of Budget and Management shall accordingly issue the Advice of Allotment to effect the necessary adjustment without prejudice to the immediate implementation of the realignment by the concerned implementing agencies."}},{"id":"PH-H5327-A59","no":59,"noLabel":{"en":"Section 59."},"text":{"en":"Release of Funds. Release of funds for NALGU, construction, repair and maintenance, rehabilitation, replacement, completion, betterment or improvement of roads and bridges, port works, flood control, waterworks/supply and government buildings and structures shall be released with at least f if-teen (15) days prior writ-ten notice -to the representative of -the district concerned."}},{"id":"PH-H5327-A60","no":60,"noLabel":{"en":"Section 60."},"text":{"en":"Appropriation Reserve. There shall be established a mandatory reserve in -the amount equivalent to ten percent (10%) of the total non-personal services appropriations excluding appropriations for school buildings, hospital buildings and court houses for FY 1990 of all agencies and offices of -the national government, including all government-owned and/or controlled corporations and the Congress of the Philippines.\nShould conditions during the fiscal year warrant the use of the reserve, the same shall be released subject to the submission of a report by the Secretary of Budget and Management to the Congress of the Philippines within ten (10) days from the date of said release."}},{"id":"PH-H5327-A61","no":61,"noLabel":{"en":"Section 61."},"text":{"en":"Payment of the Philippine Nuclear Power Plant loan. Any and all payments for the balance that may still be due or sought to be collected from the Republic of the Philippines on the loans connected with the Philippine Nuclear Power Plant are hereby expressedly disauthorized, all laws and issuances to the contrary notwithstanding."}},{"id":"PH-H5327-A62","no":62,"noLabel":{"en":"Section 62."},"text":{"en":"Separability Clause. If for any reason any section or provision of this Act is declared unconstitutional or invalid, other sections or provisions hereof which are not affected thereby shall continue to be in full force and effect."}},{"id":"PH-H5327-A63","no":63,"noLabel":{"en":"Section 63."},"text":{"en":"Effectivity. The provisions of this Act shall take effect on January one, nineteen hundred and ninety, unless otherwise provided herein."}}],"pack":"ph-p75"};
  FT["PH-H5328"] = {"id":"PH-H5328","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1990/ra_6832_1990.html","fetchedAt":"2026-10-06","articleCount":17,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating a Commission to Conduct a Thorough Fact-Finding Investigation of the Failed Coup D?État of December 1989, Recommend Measures to Prevent the Occurrence of Similar Attempts at a Violent Seizure of Power, and for Other Purposes","orig":"An Act Creating a Commission to Conduct a Thorough Fact-Finding Investigation of the Failed Coup D?État of December 1989, Recommend Measures to Prevent the Occurrence of Similar Attempts at a Violent Seizure of Power, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6832","issuingBody":"Congress of the Philippines","promulgatedDate":"1990-01-05","completenessNote":"全文，共 17 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1990/ra_6832_1990.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5328-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Creation, Objectives and Powers. – There is hereby created an independent Commission which shall investigate all the facts and circumstances of the failed coup d′État of December 1989, and recommend measures to prevent similar attempts at a violent seizure of power.\nTo attain these objectives, the Commission shall:\n(a) Conduct a thorough fact-finding investigation of the said coup d′État and the involvement therein of military personnel and civilian personalities including public officials and employees, evaluate all the facts and circumstances of the same, and submit its findings and recommendation to the President, the Congress, and other appropriate authorities not later that one (1) year from the effectivity of this Act;\n(b) Receive, review and evaluate the evidence adduced and to this end, summon witnesses, administer oaths, take testimony or receive evidence relevant to the investigation, and to issue subpoena ad testificandum or subpoena duces tecum to produce documents, books, records and other papers;\n(c) Turn over to the appropriate prosecutorial authorities all evidence involving any person when in the course of its investigation, the Commission finds that there is reasonable ground to believe that he appears to be liable for any criminal offense in connection with said coup d′État.\n(d) Ask the Monetary Board to disclose information on and/or to grant authority to examine any bank deposits, trust or investment funds, or banking transactions in the name of and/or utilized by a person, natural or juridical, under investigation by the Commission, in any bank or banking institution in the Philippines, when the Commission has reasonable ground to believe that actions have been used in support or furtherance of the objectives of said coup d′État; and\n(e) Exercise such other acts incident to or are appropriate and necessary in connection with the objectives of this Act."}},{"id":"PH-H5328-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Bar Against Court Injunction; Exception, Supreme Court. – No court, except the Supreme Court, shall issue any restraining order or preliminary injunction on any matter involving the official acts of the Commission pursuant to this Act and of the Monetary Board under paragraph (d) of Section 1 hereof."}},{"id":"PH-H5328-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Composition, Qualification and Salary. – The Commission shall be composed of a Chairman and four (4) members who shall be appointed by the President. The Chairman and members shall be citizens of the Philippines, at least thirty-five (35) years of age, and have an established reputation for integrity, honesty, probity and professional competence. They shall receive the same salary as the Chairman and members, respectively, of the Constitutional Commission."}},{"id":"PH-H5328-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Tenure and Turn Over of Records. – The Commission is hereby given one (1) year from the effectivity of this Act to attain the objectives set forth herein. Two (2) months after the lapse of said period, the Commission shall be functus officio, and shall turn over all its records, assets and properties to the Department of Justice."}},{"id":"PH-H5328-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Orderly Conduct of Proceedings. – The Commission shall adopt rules and procedures for orderly conduct of its investigation, proceeding and hearing, including the presentation of evidence. The rules of evidence under the Revised Rules of Court shall have suppletory application."}},{"id":"PH-H5328-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Conduct of Hearings. – Proceedings and hearings of the Commission, sitting en banc, shall be open to the public. The Commission may, motu proprio or upon request of the person testifying, hold an executive or closed-door hearing where matters of national security or public safety are involved or the personal safety of the witness warrants the holding of such executive or closed-door hearing. The Commission shall prescribe the rules to govern such executive or closed-door hearings.\nAny person called to testify before the Commission shall have the right to counsel at any stage of the proceedings."}},{"id":"PH-H5328-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Right Against Self-Incrimination; Protection of Witness. – No person shall be excused from attending and testifying or from producing documents, books, records, correspondence, or other evidence in obedience to a subpoena issued by the Commission on the ground that his testimony or other evidence required of him may tend to incriminate him or subject him to penalty or forfeiture. After having invoked his right against self-incrimination, his testimony or any evidence produced by him shall not be used against him in any proceedings, except for perjury committed in so testifying.\nThe Commission shall protect any person called to testify by providing the necessary and reasonable security arrangements with the assistance and cooperation of the Armed Forces of the Philippines and other appropriate government agencies."}},{"id":"PH-H5328-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Immunity from Criminal Prosecution. – The Commission is authorized to grant immunity from criminal prosecution to any person who provides information or testifies in any investigation conducted by it where, upon its evaluation, such information or testimony is necessary and vital to the investigation. The immunity thereby granted shall continue to protect the witness who repeats such testimony before the appropriate court when required to do so by the latter. Should he refuse to repeat such testimony, the immunity granted him shall cease."}},{"id":"PH-H5328-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Direct or Indirect Contempt. – The Commission may hold any person in direct or indirect contempt, and impose appropriate penalties therefor.\nA person guilty of misbehavior in the presence of or so near the Commission as to obstruct or interrupt the proceedings before the same, including disrespect towards its officials, offensive personalities towards other, or refusal to be sworn or to answer as a witness or to subscribe to an affidavit or deposition when lawfully required to do so, may be summarily adjudged in direct contempt by the Commission and punished with a fine not exceeding Five thousand pesos (P5,000.00) or imprisonment not exceeding thirty (30) days or both. The judgment of the Commission on direct contempt shall be final and not appealable.\nIndirect contempt shall be dealt by the Commission in the manner prescribed under Rule 71 of the Revised Rules of Court."}},{"id":"PH-H5328-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Personnel of the Commission. – The Chairman shall have the power to engage the services of such persons or personnel including a Commission Counsel, Deputy Commission Counsel(s) or such other officials as may be required for the effective performance of its functions and responsibilities, to fix their duties and compensation, to organize the structure and staffing pattern of the Commission; and to authorize the payment of honoraria and/or allowance for deputized officers and officials subject to the pertinent accounting and auditing rules and procedures. The persons, appointed, designated, deputized or contracted by the Commission shall be subject to the Civil Service Law, rules and regulations."}},{"id":"PH-H5328-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Promulgation of Rules and Regulations; Publication of Rules and Reports. – The Commission shall have the power to promulgate its rules and regulations, enter into contracts, and perform any and all other acts necessary or incidental to the attainment of the objectives of this Act.\nCommission rules and regulations shall be published in at least two (2) national newspapers of general circulation and shall take effect two (2) days after its publication. The final report to the President and to Congress shall be published."}},{"id":"PH-H5328-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Role of Other Government Agencies. – The Commission may call upon any government investigative and prosecutorial agency, including the National Bureau of Investigation and the Philippine Constabulary/Integrated National Police, to make available their offices, personnel and facilities to attain the objectives of this Act."}},{"id":"PH-H5328-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Appropriations. – The sum of Ten million pesos (P10,000,000.00) is hereby provided to the Commission, chargeable against the Contingent Fund. The said amount shall automatically be released to the Commission for disbursement by it in accordance with the auditing rules and regulations."}},{"id":"PH-H5328-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Transfer of Records and Facilities to the Commission. – The records, facilities, equipment, property, rights and such other things incidental to the creation of the Presidential Commission under Administrative Order No. 146, Series of 1989, are hereby transferred to the Commission created by this Act: Provided, That employees of the Presidential Commission, particularly the rank and file, shall be absorbed by the Commission to the extent that it is administratively feasible."}},{"id":"PH-H5328-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Applicable Law in Case of Conflict. – The provisions of this Act shall prevail over other laws, acts, executive orders, administrative orders, issuances, rules and regulations or parts thereof, of the Revised Rules of Court as regards the subject matter of this Act."}},{"id":"PH-H5328-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Separability Clause. – If any provision of this Act is declared unconstitutional, the same shall not affect the validity and effectivity of the other provisions hereof."}},{"id":"PH-H5328-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Effectivity. – This Act shall take effect two (2) days following its publication in at least two (2) national newspapers of general circulation."}}],"pack":"ph-p75"};
  FT["PH-H5329"] = {"id":"PH-H5329","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1990/ra_6839_1990.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Renaming the Ilijan Elementary School to Pedro S. Tolentino Memorial Elementary School","orig":"An Act Renaming the Ilijan Elementary School to Pedro S. Tolentino Memorial Elementary School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 6839","issuingBody":"Congress of the Philippines","promulgatedDate":"1990-01-05","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1990/ra_6839_1990.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5329-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Ilijan Elementary School located in Barangay Ilijan, City of Batangas, is hereby renamed as the Pedro S. Tolentino Memorial Elementary School."}},{"id":"PH-H5329-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: January 5, 1990."}}],"pack":"ph-p75"};
  FT["PH-H5330"] = {"id":"PH-H5330","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1990/ra_6840_1990.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Paaralang Elementarya ng Bading in Butuan City to Paaralang Elementarya ng Obrero","orig":"An Act Changing the Name of the Paaralang Elementarya ng Bading in Butuan City to Paaralang Elementarya ng Obrero"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6840","issuingBody":"Congress of the Philippines","promulgatedDate":"1990-01-05","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1990/ra_6840_1990.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5330-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Paaralang Elementarya ng Bading in Butuan City is hereby changed to Paaralang Elementarya ng Obrero."}},{"id":"PH-H5330-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: January 5, 1990."}}],"pack":"ph-p75"};
  FT["PH-H5331"] = {"id":"PH-H5331","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1990/ra_6841_1990.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Manggahan Elementary School Unit I in the Municipality of Pasig, Metro Manila, to San Lorenzo Ruiz Elementary School","orig":"An Act Changing the Name of the Manggahan Elementary School Unit I in the Municipality of Pasig, Metro Manila, to San Lorenzo Ruiz Elementary School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 6841","issuingBody":"Congress of the Philippines","promulgatedDate":"1990-01-05","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1990/ra_6841_1990.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5331-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Manggahan Elementary School Unit I in the Municipality of Pasig, Metro Manila, is hereby changed to San Lorenzo Ruiz Elementary School."}},{"id":"PH-H5331-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: January 5, 1990."}}],"pack":"ph-p75"};
  FT["PH-H5332"] = {"id":"PH-H5332","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1990/ra_6842_1990.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Create the Municipality of San Jose in the Province of Tarlac","orig":"An Act to Create the Municipality of San Jose in the Province of Tarlac"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6842","issuingBody":"Congress of the Philippines","promulgatedDate":"1990-01-05","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1990/ra_6842_1990.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5332-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Barangays Burgos, Iba, Labney, Lawacamulag, David, Lubigan, Maamot, Mababanaba, Moriones, Pao, San Juan de Valdez, Sula and Villa Aglipay in the Municipality of Tarlac, Province of Tarlac, are hereby separated from said municipality and constituted into a distinct and independent municipality to be known as the Municipality of San Jose, Tarlac, with the seat of government at the present site of Barangay Villa Aglipay."}},{"id":"PH-H5332-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Municipality of San Jose shall be bounded on the East by Barangays Sto. Domingo Sapang Maragul, Tibag, and Armenia of the Municipality of Tarlac; on the West by the Province of Zambales; on the South by the Municipality of Capas; and the North by the Municipalities of Sta. Ignacia and Mayantoc."}},{"id":"PH-H5332-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Municipality of San Jose shall begin to exist upon the ratification by a majority of the votes cast in a plebiscite to be conducted in the areas affected within one hundred twenty (120) days after the approval of this Act.\nThe Commission on Elections shall conduct and supervise the plebiscite. The expenses in holding the plebiscite shall be taken out of the Contingent Fund under the current fiscal year appropriations."}},{"id":"PH-H5332-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The first mayor, vice-mayor and councilors of the new municipality shall be appointed by the President and shall serve until noon of June 30, 1992."}},{"id":"PH-H5332-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Upon approval of this Act, the municipal treasurer of Tarlac, Tarlac, shall turn over such amount of real estate taxes and other fees collected from the barangays mentioned in Section 1 hereof to the municipal treasurer of the Municipality of San Jose, Tarlac."}},{"id":"PH-H5332-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon publication in at least two (2) newspapers of general circulation.\nApproved: January 5, 1990."}}],"pack":"ph-p75"};
  FT["PH-H5333"] = {"id":"PH-H5333","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1990/ra_6843_1990.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Amend Section Ninety-Six of Republic Act Numbered Forty-Four Hundred and Eighty-Seven, Entitled \"An Act Creating the City of San Carlos in Pangasinan\" by Allowing Qualified Voters of the City of San Carlos to Vote in the Provincial Elections of the Province of Pangasinan","orig":"An Act to Amend Section Ninety-Six of Republic Act Numbered Forty-Four Hundred and Eighty-Seven, Entitled \"An Act Creating the City of San Carlos in Pangasinan\" by Allowing Qualified Voters of the City of San Carlos to Vote in the Provincial Elections of the Province of Pangasinan"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 6843","issuingBody":"Congress of the Philippines","promulgatedDate":"1990-01-05","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1990/ra_6843_1990.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5333-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Amendment.— Section Ninety-six of Republic Act Numbered Forty-four hundred and eighty-seven entitled \"An Act Creating the City of San Carlos in Pangasinan,\" is hereby amended to read as follows:\n\"Sec. 96. Participation in Elections of Provincial Officials.— The voters of the City of San Carlos shall be qualified and entitled to vote in the elections of provincial board of the Province of Pangasinan, and any such qualified voters can be a candidate for any provincial office.\""}},{"id":"PH-H5333-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Repealing Clause.— All existing laws or parts thereof inconsistent with the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H5333-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Effectivity.— This Act shall take effect upon its approval.\nApproved: January 5, 1990."}}],"pack":"ph-p75"};
  FT["PH-H5334"] = {"id":"PH-H5334","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1990/ra_6844_1990.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Marcos Bridge in Barangay Lauis, Municipality of Candelaria, Province of Zambales, to Lauis Bridge","orig":"An Act Changing the Name of the Marcos Bridge in Barangay Lauis, Municipality of Candelaria, Province of Zambales, to Lauis Bridge"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 6844","issuingBody":"Congress of the Philippines","promulgatedDate":"1990-01-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1990/ra_6844_1990.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5334-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Marcos Bridge in Barangay Lauis, Municipality of Candelaria, Province of Zambales, is hereby changed to Lauis Bridge."}},{"id":"PH-H5334-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: January 18, 1990."}}],"pack":"ph-p75"};
